// Watermark-based fetch (spec Section 5) -- read the last date_received we
// successfully advanced past, or fall back to an initial lookback window on
// the very first run.
//
// Why a lookback window and not "since yesterday": the CFPB Consumer Complaint
// Database only publishes a complaint once the company has responded or 15
// calendar days have passed (spec Section 3b, the CFPB 15-day rule). A poll
// watermarked to "yesterday" would mostly return nothing. INITIAL_LOOKBACK_DAYS
// gives the first run a realistic chance of hits while still behaving like a
// genuine incremental poller from the second run onward.
const INITIAL_LOOKBACK_DAYS = 30;

const staticData = $getWorkflowStaticData('node');

let watermarkDate = staticData.lastWatermarkDate;
let isFirstRun = false;

if (!watermarkDate) {
  isFirstRun = true;
  const fallback = new Date();
  fallback.setUTCDate(fallback.getUTCDate() - INITIAL_LOOKBACK_DAYS);
  watermarkDate = fallback.toISOString().slice(0, 10); // YYYY-MM-DD
}

return [
  {
    json: {
      watermarkDate,
      isFirstRun,
    },
  },
];

// Cap to 25/run (spec Section 5 -- cost predictability, not a rate-limit
// necessity; size=25 is already set on the request, this is a defensive
// second cap), flatten each ES hit down to the fields the rest of the
// pipeline needs (spec Section 3a), and advance the watermark to the latest
// date_received actually seen in this batch.
//
// Watermark precision note: CFPB's date_received_min filter is date-level
// (YYYY-MM-DD), not timestamp-level -- confirmed live during Phase 1 build
// (a sub-day timestamp is rejected by the API). That means a same-day poll
// can re-return complaints already fetched earlier that day. This workflow
// does not dedup here by design -- spec Section 11 assigns dedup to the
// storage layer ("Google Sheets Append-or-Update, dedup via complaint ID"),
// wired in a later phase. Downstream nodes must not assume every item here
// is new.
const MAX_PER_RUN = 25;

const response = $input.first().json;
const hits = (response.hits && response.hits.hits) || [];
const capped = hits.slice(0, MAX_PER_RUN);

const staticData = $getWorkflowStaticData('node');
let maxDate = staticData.lastWatermarkDate || null;

const out = capped.map((hit) => {
  const src = hit._source;
  const received = (src.date_received || '').slice(0, 10);
  if (received && (!maxDate || received > maxDate)) {
    maxDate = received;
  }
  return {
    json: {
      complaint_id: src.complaint_id,
      product: src.product,
      sub_product: src.sub_product,
      issue: src.issue,
      sub_issue: src.sub_issue,
      company: src.company,
      state: src.state,
      tags: src.tags,
      date_received: src.date_received,
      timely: src.timely,
      company_response: src.company_response,
      complaint_what_happened: src.complaint_what_happened,
    },
  };
});

if (maxDate) {
  staticData.lastWatermarkDate = maxDate;
}

return out;

// Synthetic customer/account record generator (spec Section 3c).
//
// Structured like a real bank CRM export -- tenure, tier, holdings, balance,
// contact history -- but every field is synthetic EXCEPT linked_complaint_id
// (the real CFPB complaint ID) and the two flags below, which carry forward
// CFPB's own real `tags` field where it exists. That carry-forward is the
// deliberately-real part of an otherwise-synthetic record (spec Section 12) --
// never blur it with the rest, and never let this record be mistaken for a
// real CRM export in any downstream dashboard/report (Section 14).
//
// Deterministic, not random-per-run: seeded from complaint_id (mulberry32 PRNG)
// so re-processing the same ticket -- a retry, a re-run, a dedup pass hitting
// the same complaint_id twice because of the date-level watermark overlap
// noted upstream -- always yields the same synthetic record instead of a new
// random one each time.

function mulberry32(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function seedFromString(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function weightedPick(rng, weighted) {
  const total = weighted.reduce((s, [, w]) => s + w, 0);
  let r = rng() * total;
  for (const [value, weight] of weighted) {
    if (r < weight) return value;
    r -= weight;
  }
  return weighted[weighted.length - 1][0];
}

const PRODUCT_POOL = [
  'Checking Account', 'Savings Account', 'Credit Card', 'Personal Loan',
  'Auto Loan', 'Mortgage', 'Home Equity Line of Credit', 'Certificate of Deposit',
];

const items = $input.all();

const out = items.map((item) => {
  const ticket = item.json;
  const rng = mulberry32(seedFromString(String(ticket.complaint_id)));

  const tenure_years = weightedPick(rng, [[0,3],[1,4],[2,4],[3,4],[4,3],[5,3],[6,2],[7,2],[8,1],[9,1],[10,1],[12,1],[15,1]]);
  const received = new Date(ticket.date_received);
  const since = new Date(received);
  since.setUTCFullYear(since.getUTCFullYear() - tenure_years);
  since.setUTCMonth(Math.floor(rng() * 12));
  since.setUTCDate(1 + Math.floor(rng() * 28));
  const customer_since = since.toISOString().slice(0, 10);

  const account_tier = weightedPick(rng, [['Standard', 7], ['Preferred', 2], ['Premier', 1]]);

  const holdingsCount = weightedPick(rng, [[1, 5], [2, 3], [3, 1], [4, 1]]);
  const shuffled = [...PRODUCT_POOL].sort(() => rng() - 0.5);
  const product_holdings = shuffled.slice(0, holdingsCount);

  const outstanding_balance_usd = weightedPick(rng, [[0, 3], [1, 1]]) === 0
    ? 0
    : Math.round(rng() * 15000 * 100) / 100;

  const prior_complaints_12mo = weightedPick(rng, [[0, 6], [1, 2], [2, 1], [3, 1]]);
  const prior_contacts_90d = weightedPick(rng, [[0, 4], [1, 3], [2, 2], [3, 1], [4, 1]]);
  const preferred_channel = weightedPick(rng, [['Web', 5], ['Phone', 3], ['Mail', 1]]);

  // Real-tag carry-forward (spec Section 3c/12). CFPB's own `tags` field is
  // real government data, not synthetic. Values seen in the wild: null,
  // "Servicemember", "Older American", or "Older American, Servicemember".
  // special_population_flag is the broader of the two -- CFPB itself treats
  // servicemembers and older Americans together as populations warranting
  // extra-care handling, so a Servicemember tag sets both flags true.
  const tags = ticket.tags || '';
  const servicemember_flag = tags.includes('Servicemember');
  const special_population_flag = tags.includes('Servicemember') || tags.includes('Older American');

  return {
    json: {
      ...ticket,
      crm: {
        account_id: `SYN-${seedFromString(String(ticket.complaint_id)).toString(36).toUpperCase()}`,
        linked_complaint_id: String(ticket.complaint_id),
        customer_since,
        tenure_years,
        account_tier,
        product_holdings,
        outstanding_balance_usd,
        prior_complaints_12mo,
        prior_contacts_90d,
        preferred_channel,
        servicemember_flag,
        special_population_flag,
      },
    },
  };
});

return out;

// Both the live pipeline (Phase 1 fetch -> Phase 2 CRM) and the Fixture Test
// Trigger converge here. Phase 3's mock agents only have known-good fixture
// data for Tickets A/B/C -- route anything else to a clearly-labelled
// "awaiting Phase 7" dead end instead of letting it fall through into agents
// that would have to fabricate a result for it.
const FIXTURE_IDS = ["9999970","9999975","9999983"];
const ticket = $input.item.json;
return { json: { ...ticket, is_fixture_ticket: FIXTURE_IDS.includes(String(ticket.complaint_id)) } };

// Real ticket, real synthetic CRM (Phase 1/2 both genuinely ran) -- just no
// agent decision, since Phase 3's mock agents only have fixture data for
// Tickets A/B/C. Carries the real fields already computed upstream rather
// than the bare complaint_id/product this used to return, so a dashboard
// can show something useful for these instead of just a count -- still
// zero fabricated reasoning: no severity, no draft, no escalation call.
const t = $input.item.json;
return {
  json: {
    complaint_id: t.complaint_id, company: t.company, product: t.product, state: t.state,
    issue: t.issue, sub_issue: t.sub_issue, tags: t.tags, date_received: t.date_received,
    timely: t.timely, company_response: t.company_response,
    crm_summary: t.crm ? { account_tier: t.crm.account_tier, tenure_years: t.crm.tenure_years, special_population_flag: t.crm.special_population_flag } : null,
    decision: "AWAITING_PHASE_7",
    note: "Live ticket -- no Phase 3 mock fixture exists for this complaint_id. Awaiting the real Claude API swap at Phase 7.",
  },
};

// Agent 1: Classification -- MOCKED reasoning layer (spec Section 15 Phase 3).
// Returns the literal Section 6 fixture output for Tickets A/B/C. The tool
// this agent conditionally calls (taxonomy lookup) is real -- see the next
// node -- only the classification judgment itself is mocked here.
